package be.winnetrie.mod.simpleserverutilities.client.gui;import be.winnetrie.mod.simpleserverutilities.moderation.PlayerInventoryAdminMenu;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class PlayerInventoryAdminScreen extends AbstractContainerScreen<PlayerInventoryAdminMenu>{public PlayerInventoryAdminScreen(PlayerInventoryAdminMenu m,Inventory i,Component t){super(m,i,t,196,250);titleLabelX=inventoryLabelX=-10000;}@Override protected void init(){super.init();addRenderableWidget(Button.builder(Component.literal("Close & save"),b->minecraft.player.closeContainer()).bounds(leftPos+96,topPos+imageHeight-24,86,18).build());}@Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){int rows=(menu.targetSlots()+8)/9;g.fill(0,0,width,height,0xA5000000);g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xF0161D25);g.outline(leftPos,topPos,imageWidth,imageHeight,0xFF586978);g.text(font,(menu.mode().equals("ender")?"Ender chest — ":"Inventory & equipment — ")+menu.targetName(),leftPos+12,topPos+10,0xFFF3F5F7,true);g.text(font,"Target",leftPos+12,topPos+23,0xFFAAB5BE,false);for(int i=0;i<menu.targetSlots();i++){int x=leftPos+17+(i%9)*18,y=topPos+34+(i/9)*18;g.fill(x-1,y-1,x+17,y+17,0xFF090D12);g.outline(x-1,y-1,18,18,0xFF485865);}g.text(font,"Administrator inventory",leftPos+12,topPos+34+rows*18+7,0xFFAAB5BE,false);super.extractRenderState(g,mx,my,pt);}@Override public boolean isPauseScreen(){return false;}}
